```java
@Service
public class IdempotencyService {
    private final IdempotencyRepository repo;
    private final TransactionTemplate txTemplate;
    private final ObjectMapper objectMapper;

    public IdempotencyService(IdempotencyRepository repo, PlatformTransactionManager txManager, ObjectMapper objectMapper) {...}

    public IdemOutcome execute(String requestId, String operation, String actor, String resource,
                               Map<String, Object> params, Supplier<Object> business) {
        String fingerprint = canonical(params);
        Optional<IdempotencyRecord> existing = repo.findByRequestId(requestId);
        if (existing.isPresent()) {
            return resolve(existing.get(), fingerprint);
        }
        try {
            return txTemplate.execute(status -> {
                repo.insertPending(requestId, operation, actor, resource, fingerprint, Instant.now());
                Object result = business.get();
                IdemOutcome outcome = serialize(result);
                repo.complete(requestId, outcome.status(), outcome.body());
                return outcome;
            });
        } catch (DuplicateKeyException ex) {
            return resolveAfterRace(requestId, fingerprint);
        }
    }
}
```

